45	// TestBatchMutualSwapSucceeds is the headline scenario: originally B depends
46	// on A. Submitting "A depends on B, B becomes root" must succeed because the
47	// legality is judged on the graph AFTER all replacements.
48	func TestBatchMutualSwapSucceeds(t *testing.T) {
49		graph := buildGraph(t, P("A"), P("B", "A"))
50		plan := planOf(change("A", "B"), change("B"))
51	
52		report, err := PreviewBatch(graph, plan)
53		if err != nil {
54			t.Fatalf("PreviewBatch unexpected error: %v", err)
55		}
56		if got := graph["A"].Parents; len(got) != 0 {
57			t.Fatalf("preview mutated graph: A.Parents = %v", got)
58		}
59	
60		wantChanged := []string{"A", "B"}
61		if !reflect.DeepEqual(report.ChangedDatasets, wantChanged) {
62			t.Errorf("ChangedDatasets = %v, want %v", report.ChangedDatasets, wantChanged)
63		}
64		if len(report.NewDatasets) != 0 {
65			t.Errorf("NewDatasets = %v, want empty", report.NewDatasets)
66		}
67		wantAdded := []Relation{{Upstream: "B", Downstream: "A"}}
68		wantRemoved := []Relation{{Upstream: "A", Downstream: "B"}}
69		if !reflect.DeepEqual(report.AddedRelations, wantAdded) {
70			t.Errorf("AddedRelations = %v, want %v", report.AddedRelations, wantAdded)
71		}
72		if !reflect.DeepEqual(report.RemovedRelations, wantRemoved) {
73			t.Errorf("RemovedRelations = %v, want %v", report.RemovedRelations, wantRemoved)
74		}
75		// No downstream is affected: the swap only repoints A and B, and neither
76		// has other dependents.
77		if len(report.AffectedDownstreams) != 0 {
78			t.Errorf("AffectedDownstreams = %v, want empty", report.AffectedDownstreams)
79		}
80	
81		// Apply and verify the final shape: A depends on B, B is a root.
82		applied, err := ApplyBatch(graph, plan)
83		if err != nil {
84			t.Fatalf("ApplyBatch unexpected error: %v", err)
85		}
86		if !reflect.DeepEqual(applied, report) {
87			t.Errorf("apply report differs from preview:\n apply=%#v\n preview=%#v", applied, report)
88		}
89		if got := graph["A"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
90			t.Errorf("A.Parents = %v, want [B]", got)
91		}
92		if got := graph["B"].Parents; len(got) != 0 {
93			t.Errorf("B.Parents = %v, want empty (root)", got)
94		}
95		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"A"}) {
96			t.Errorf("B.Children = %v, want [A]", got)
97		}
98		if got := graph["A"].Children; len(got) != 0 {
99			t.Errorf("A.Children = %v, want empty", got)
100		}
101		if roots := Roots(graph); !reflect.DeepEqual(roots, []string{"B"}) {
102			t.Errorf("Roots = %v, want [B]", roots)
103		}
104	}
