106	// TestBatchRejectsCyclesAfterReplacement verifies that a final graph with a
107	// self-dependency or an indirect cycle is rejected, and that the rejection
108	// names the datasets involved.
109	func TestBatchRejectsCyclesAfterReplacement(t *testing.T) {
