403				t.Fatalf("PreviewBatch unexpected error: %v", err)
404			}
405			wantAffected := []string{"C"}
406			if !reflect.DeepEqual(report.AffectedDownstreams, wantAffected) {
407				t.Errorf("AffectedDownstreams = %v, want %v", report.AffectedDownstreams, wantAffected)
408			}
409		})
410	
411		t.Run("deleted edge still counts from original graph", func(t *testing.T) {
412			// A<-B<-C. B becomes a root (edge A-B removed). C is still downstream
413			// of B in the final graph, but the impact also follows the original
414			// graph: B's children in the original include C. Either way C is
415			// affected. The key case is when a removed edge hides a dependent in
416			// the final graph.
417			//
418			// A<-B, A<-C (B and C both depend on A). Plan: B becomes root. In the
419			// final graph B has no children, but in the original graph B's children
420			// are empty too. The real test: a dataset that was downstream of B in
421			// the original graph only.
422			//
423			// Construct: A<-B<-C, and C also depends on A. Plan: B becomes root.
424			// Final: B root, C depends on A. C is downstream of B in the original
425			// graph (B->C) but not in the final graph. C must still be affected
426			// because the impact follows the original graph too.
427			graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B", "A"))
428			plan := planOf(change("B"))
429			report, err := PreviewBatch(graph, plan)
430			if err != nil {
431				t.Fatalf("PreviewBatch unexpected error: %v", err)
432			}
433			wantAffected := []string{"C"}
434			if !reflect.DeepEqual(report.AffectedDownstreams, wantAffected) {
435				t.Errorf("AffectedDownstreams = %v, want %v (original-graph dependent must still count)", report.AffectedDownstreams, wantAffected)
436			}
437		})
438	
439		t.Run("seeds excluded and paths deduped", func(t *testing.T) {
440			// A<-B<-C and A<-C. B changes to root. C is downstream of B (original)
441			// and downstream of A (unchanged). C is affected once, not twice.
442			graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B", "A"))
443			plan := planOf(change("B"))
444			report, err := PreviewBatch(graph, plan)
445			if err != nil {
446				t.Fatalf("PreviewBatch unexpected error: %v", err)
447			}
448			count := 0
449			for _, name := range report.AffectedDownstreams {
450				if name == "C" {
451					count++
452				}
453			}
454			if count != 1 {
455				t.Errorf("C counted %d times in AffectedDownstreams %v, want once", count, report.AffectedDownstreams)
456			}
457			// B is a seed (changed) and must not appear in affected.
458			for _, name := range report.AffectedDownstreams {
459				if name == "B" {
460					t.Errorf("seed B appears in AffectedDownstreams %v, must be excluded", report.AffectedDownstreams)
461				}
462			}
463		})
464	
465		t.Run("new dataset with downstream", func(t *testing.T) {
466			// A is new. B (existing) now depends on A, so B is a changed seed. C
467			// depends on B and is unchanged, so C is affected (reachable from the
468			// new dataset A via B in the final graph).
469			graph := buildGraph(t, P("B"), P("C", "B"))
470			plan := planOf(change("A"), change("B", "A"))
471			report, err := PreviewBatch(graph, plan)
472			if err != nil {
473				t.Fatalf("PreviewBatch unexpected error: %v", err)
474			}
475			wantAffected := []string{"C"}
476			if !reflect.DeepEqual(report.AffectedDownstreams, wantAffected) {
477				t.Errorf("AffectedDownstreams = %v, want %v", report.AffectedDownstreams, wantAffected)
478			}
479		})
480	}
481	
482	// TestBatchDeterministicOutput verifies that the same current graph and plan
483	// produce byte-identical success output even when records and upstreams are in
484	// a different order.
485	func TestBatchDeterministicOutput(t *testing.T) {
486		build := func() map[string]*Lineage {
487			return buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
488		}
489		// Plan 1: shuffled order, shuffled upstreams with duplicates.
490		plan1 := planOf(
491			change("D", "C"),
492			change("B"),
493			change("C", "A", "A"),
494		)
495		// Plan 2: different record order, different upstream order, no duplicates.
496		plan2 := planOf(
497			change("C", "A"),
498			change("D", "C"),
499			change("B"),
500		)
501	
502		g1 := build()
503		r1, err := ApplyBatch(g1, plan1)
504		if err != nil {
505			t.Fatalf("ApplyBatch plan1 unexpected error: %v", err)
506		}
507		g2 := build()
508		r2, err := ApplyBatch(g2, plan2)
509		if err != nil {
510			t.Fatalf("ApplyBatch plan2 unexpected error: %v", err)
511		}
512	
513		b1, err := MarshalGraphFile(g1)
514		if err != nil {
515			t.Fatalf("MarshalGraphFile g1 unexpected error: %v", err)
516		}
517		b2, err := MarshalGraphFile(g2)
518		if err != nil {
519			t.Fatalf("MarshalGraphFile g2 unexpected error: %v", err)
520		}
521		if string(b1) != string(b2) {
522			t.Fatalf("graph bytes differ:\n--- plan1 ---\n%s\n--- plan2 ---\n%s", b1, b2)
523		}
524	
525		// Reports must also be identical.
526		rb1, err := json.Marshal(r1)
527		if err != nil {
528			t.Fatalf("json.Marshal r1 unexpected error: %v", err)
529		}
530		rb2, err := json.Marshal(r2)
531		if err != nil {
532			t.Fatalf("json.Marshal r2 unexpected error: %v", err)
533		}
534		if string(rb1) != string(rb2) {
535			t.Fatalf("report bytes differ:\n--- plan1 ---\n%s\n--- plan2 ---\n%s", rb1, rb2)
536		}
537	}
538	
539	// TestBatchPreviewApplyConsistency verifies that preview and apply produce the
540	// same report for the same current graph and plan.
541	func TestBatchPreviewApplyConsistency(t *testing.T) {
542		graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
543		plan := planOf(change("B"), change("C", "A"))
544	
545		preview, err := PreviewBatch(graph, plan)
546		if err != nil {
547			t.Fatalf("PreviewBatch unexpected error: %v", err)
548		}
549		applied, err := ApplyBatch(graph, plan)
550		if err != nil {
551			t.Fatalf("ApplyBatch unexpected error: %v", err)
552		}
553		if !reflect.DeepEqual(preview, applied) {
554			t.Fatalf("preview and apply reports differ:\n preview=%#v\n applied=%#v", preview, applied)
555		}
556	}
557	
558	// TestBatchJSONRoundTrip verifies that a graph marshaled to JSON and parsed
559	// back is equivalent, and that empty lists encode as [].
560	func TestBatchJSONRoundTrip(t *testing.T) {
561		graph := buildGraph(t, P("A"), P("B", "A"))
562		data, err := MarshalGraphFile(graph)
563		if err != nil {
564			t.Fatalf("MarshalGraphFile unexpected error: %v", err)
565		}
566		parsed, err := UnmarshalGraphFile(data)
567		if err != nil {
568			t.Fatalf("UnmarshalGraphFile unexpected error: %v", err)
569		}
570		if !reflect.DeepEqual(parsed, graph) {
571			t.Fatalf("round-trip mismatch:\n got %#v\nwant %#v", parsed, graph)
572		}
573	
574		// Empty graph encodes datasets as [].
575		empty := map[string]*Lineage{}
576		data, err = MarshalGraphFile(empty)
577		if err != nil {
578			t.Fatalf("MarshalGraphFile empty unexpected error: %v", err)
579		}
580		if !strings.Contains(string(data), `"datasets": []`) {
581			t.Errorf("empty graph JSON = %s, want datasets: []", data)
582		}
583	}
584	
585	// TestBatchUnmarshalRejectsInvalidGraphJSON verifies that UnmarshalGraphFile
586	// rejects structurally invalid graphs.
587	func TestBatchUnmarshalRejectsInvalidGraphJSON(t *testing.T) {
588		cases := map[string]string{
589			"empty name":      `{"datasets":[{"name":"","upstreams":[]}]}`,
590			"duplicate":       `{"datasets":[{"name":"A","upstreams":[]},{"name":"A","upstreams":[]}]}`,
591			"missing upstream": `{"datasets":[{"name":"A","upstreams":["ghost"]}]}`,
592			"cycle":           `{"datasets":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":["A"]}]}`,
593			"invalid json":    `{not json`,
594		}
595		for name, data := range cases {
596			t.Run(name, func(t *testing.T) {
597				_, err := UnmarshalGraphFile([]byte(data))
598				if err == nil {
599					t.Fatalf("expected error for %s, got nil", name)
600				}
601			})
602		}
603	}
