		if roots, ok := memo[name]; ok {
			return roots
		}
		parents := adj[name]
		if len(parents) == 0 {
			memo[name] = []string{name}
			return memo[name]
		}
		set := make(map[string]bool)
		for _, parent := range parents {
			for _, root := range walk(parent) {
				set[root] = true
			}
		}
		out := make([]string, 0, len(set))
		for root := range set {
